  ["    if v < n.Val {\n        n.Left = insert(n.___, v)\n    } else {\n        n.Right = insert(n.Right, v)\n    }\n    return n\n}\n"] = "    if v < n.Val {\n        n.Left = insert(n.___, v)\n    } else {\n        n.Right = insert(n.Right, v)\n    }\n    return n\n}\n",
