  ["#[tokio::main] builds the runtime and block_on(main()). Use #[tokio::test] in tests."] = "#[tokio::main] postaví runtime a block_on(main()). V testech použij #[tokio::test].",
  ["$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n"] = "$ cargo ___\n   Compiling delivery v0.1.0\nrunning 2 checks\nqty_parses ....... ok\neta_is_positive .. ok\nresult: ok. 2 passed; 0 failed\n",
