  ['use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n'] = 'use serde::{Deserialize, ___};\n// Cargo.toml: serde = {version="1", features=["derive"]}\n#[derive(Debug, ___, Deserialize)]\nstruct Order {\n    name: String,\n    qty: u32,\n}\n',
  ["use std::collections::HashMap;\n// station id -> the ids one hop away (an adjacency list)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // how many exits this station has\n}\n"] = "use std::collections::HashMap;\n// id stanice -> id na jeden skok daleko (seznam sousednosti)\ntype Graph = HashMap<u32, ___<u32>>;\nfn degree(g: &Graph, n: u32) -> usize {\n    g[&n].len()          // kolik má tahle stanice východů\n}\n",
  ['use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 is 1\n    println!("{:?}", count.get("t9"));    // None\n}\n'] = 'use std::collections::HashMap;\nfn main() {\n    let mut count = HashMap::new();\n    count.insert("t7", 2);\n    *count.___("t4").or_insert(0) += 1;   // t4 je 1\n    println!("{:?}", count.get("t9"));    // None\n}\n',
  ["use std::collections::HashMap; The :: walks the path. std is always there, no Cargo.toml line needed."] = "use std::collections::HashMap; Dvojtečky :: procházejí cestu. std je vždy k dispozici, žádný řádek v Cargo.toml není třeba.",
  ['use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError fits\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n'] = 'use std::error::Error;\nfn main() -> Result<(), ___<dyn Error>> {\n    let qty: i32 = "18".parse()?;   // ParseIntError se vejde\n    let text = std::fs::read_to_string("menu.txt")?;\n    println!("{qty} sets, {} bytes of menu", text.len());\n    Ok(())\n}\n',
  ['use std::fmt;\n// Receipt carries a lifetime; fmt does not need its name.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n'] = 'use std::fmt;\n// Receipt nese lifetime; fmt jeho jméno nepotřebuje.\nimpl fmt::Display for Receipt<___> {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} paid {}", self.name, self.total)\n    }\n}\n',
  ['use std::fmt;\n// Teach println!("{}") how to print an Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n'] = 'use std::fmt;\n// Nauč println!("{}"), jak vypsat Order.\nimpl fmt::___ for Order {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "{} x{}", self.bun, self.qty)\n    }\n}\n',
  ['use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n'] = 'use std::fmt;\nimpl fmt::___ for OrderError {\n    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {\n        write!(f, "order failed")\n    }\n}\n',
  ['use std::fs;\n// A missing menu file is a bug: stop with a message.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n'] = 'use std::fs;\n// Chybějící soubor s menu je bug: zastav se se zprávou.\nlet menu = fs::read_to_string("menu.txt")\n    .___("menu.txt must exist");\n',
  ["use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n"] = "use std::num::ParseIntError;\n\n#[derive(Debug)]\n___ OrderError {\n    Empty,\n    BadQty(ParseIntError),\n}\n",
  ["use std::num::ParseIntError;\n// Hand any parse error straight back to the caller.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n"] = "use std::num::ParseIntError;\n// Každou chybu parsování předej rovnou zpět volajícímu.\nfn cents(s: &str) -> Result<u32, ParseIntError> {\n    let n: u32 = s.parse()___;\n    Ok(n * 100)\n}\n",
  ["use std::sync::Arc;\n// Arc: one receiver, many owners across threads.\n// The lock: only one cook holds the rail at a time.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // one clone per cook\n"] = "use std::sync::Arc;\n// Arc: jeden příjemce, mnoho vlastníků napříč vlákny.\n// Zámek: lištu drží vždycky jen jeden kuchař.\nlet rx = Arc::new(___::new(rx));\nlet rx2 = Arc::clone(&rx);       // jeden klon na kuchaře\n",
  ['use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Many may look at once; only .write() has to wait.\nlet first = menu.___().unwrap()[0];\n'] = 'use std::sync::RwLock;\nlet menu = RwLock::new(vec!["bun", "egg tart"]);\n// Mnozí se mohou dívat najednou; čekat musí jen .write().\nlet first = menu.___().unwrap()[0];\n',
  ["use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// No lock needed: add one in a single hardware step.\nSERVED.___(1, Ordering::SeqCst);\n"] = "use std::sync::atomic::{AtomicUsize, Ordering};\nstatic SERVED: AtomicUsize = AtomicUsize::new(0);\n// Žádný zámek není třeba: přičti jedničku v jediném hardwarovém kroku.\nSERVED.___(1, Ordering::SeqCst);\n",
  ['use std::sync::mpsc;\n// One pipe from till to kitchen: a sender and a receiver.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n'] = 'use std::sync::mpsc;\n// Jedna trubka z pokladny do kuchyně: odesílatel a příjemce.\nlet (tx, rx) = mpsc::___();\ntx.send("egg tart").unwrap();\n',
  ["use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// one rail: many senders allowed, exactly one receiver\nlet (tx, rx) = mpsc::___::<Job>();\n"] = "use std::sync::mpsc;\ntype Job = Box<dyn FnOnce() + Send>;\n// jedna lišta: mnoho odesílatelů, přesně jeden příjemce\nlet (tx, rx) = mpsc::___::<Job>();\n",
  ['use std::thread;\n// The grill gets its own thread; the till keeps serving.\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n'] = 'use std::thread;\n// Gril dostane vlastní vlákno; pokladna dál obsluhuje.\nlet grill = thread::___(|| {\n    println!("bun is toasting");\n});\ngrill.join().unwrap();\n',
  ['use std::time::Duration;\n// Steep the tea for 300 ms before pouring.\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n'] = 'use std::time::Duration;\n// Louhuj čaj 300 ms, než ho naliješ.\nthread::___(Duration::from_millis(300));\nprintln!("pour");\n',
  ["utf8.RuneCountInString counts code points. []rune(s) makes them indexable."] = "utf8.RuneCountInString počítá kódové body. []rune(s) je zpřístupní indexem.",
  ["v is an any that holds a string. Take it out: s := v.(___)"] = "v je any, které drží string. Vytáhni ho: s := v.(___)",
