  ['var v any = "muffin"\ns := v.(___)              // panics if v is not one\ns2, ok := v.(string)      // safe form\n'] = 'var v any = "muffin"\ns := v.(___)              // panic, když v není string\ns2, ok := v.(string)      // bezpečná forma\n',
